<script setup>
import {computed,ref} from 'vue';import {marked} from 'marked';import content from './content.json';
const files=import.meta.glob('../source/_posts/**/*.md',{query:'?raw',import:'default',eager:true});
const parse=(raw,path)=>{const match=raw.match(/^---\n([\s\S]*?)\n---\n?/);const meta={};if(match)match[1].split('\n').forEach(line=>{const i=line.indexOf(':');if(i>0)meta[line.slice(0,i).trim()]=line.slice(i+1).trim().replace(/^['"]|['"]$/g,'')});const slug=path.split('/').pop().replace(/\.md$/,'');return{slug,title:meta.title||slug.replaceAll('-',' '),date:meta.date||'',body:raw.slice(match?match[0].length:0)}};
const posts=Object.entries(files).map(([path,raw])=>parse(raw,path)).sort((a,b)=>String(b.date).localeCompare(String(a.date)));const activeSlug=ref(decodeURIComponent(location.hash.slice(1)));addEventListener('hashchange',()=>activeSlug.value=decodeURIComponent(location.hash.slice(1)));const active=computed(()=>posts.find(post=>post.slug===activeSlug.value));const articleHtml=computed(()=>active.value?marked.parse(active.value.body):'');
</script>
<template><main class="shell page"><nav><a href="../">← Ll0veU</a><a v-if="active" href="#">All notes</a><span v-else class="eyebrow">BLOG / FIELD NOTES</span></nav><article v-if="active" class="article"><p class="eyebrow">{{active.date||'Field note'}}</p><h1>{{active.title}}</h1><div class="prose" v-html="articleHtml"></div></article><template v-else><header class="page-head"><p class="eyebrow">{{content.label}}</p><h1>{{content.headline}}</h1><p class="lede">{{content.intro}}</p></header><section class="post-list"><article v-for="post in posts" :key="post.slug" class="post-card"><span class="card-index">{{String(post.date).slice(0,4)||'NOTE'}}</span><div><h2>{{post.title}}</h2><p>{{post.date}}</p><a :href="`#${encodeURIComponent(post.slug)}`">Read note ↗</a></div></article></section></template></main></template>
